import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
import { writeFileSync } from 'node:fs';
import nodemailer from 'nodemailer';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Maya Okafor makes her Google account at Google's sign-up, as a person does (accounts.google.com/signup); her password
// is her own, made here and kept in the app's folder for her later sign-in, never a literal
const email = 'maya.okafor@gmail.com', tagged = 'maya.okafor+rallly@gmail.com';
const password = randomBytes(18).toString('base64url');
writeFileSync('.maya-password', password, { mode: 0o600 });
const signup = await fetch('https://accounts.google.com/signup', {
  method: 'POST', redirect: 'manual', headers: { 'content-type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({ email, password, given_name: 'Maya', family_name: 'Okafor', continue: 'https://mail.google.com/mail/u/0/' }),
});
assert.ok(/(?:^|[,;]\s*)SID=[^;]+/.test(signup.headers.get('set-cookie') ?? ''), `sign-up left Maya signed in to Google (status ${signup.status})`);
// Harbourline's Rallly sends through its own relay (the World's SMTP_HOST and SMTP_PORT) to the address Maya gave it,
// her tagged one: the relay hands it to Gmail, which keeps it in the account the address tags
const transport = nodemailer.createTransport({ host: process.env.SMTP_HOST, port: Number(process.env.SMTP_PORT), secure: process.env.SMTP_SECURE === 'true' });
const sent = await transport.sendMail({
  from: 'Rallly <polls@harbourline.be>', to: tagged, subject: 'Your poll has been finalized',
  text: 'The workshop is on Thursday 22 January 2026 at 10:00. Add it to your calendar.',
});
assert.deepEqual(sent.accepted, [tagged]);
assert.deepEqual(sent.rejected, []);
transport.close();
console.log(JSON.stringify({ sent: sent.messageId }));

