import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Maya, later, in a browser that holds no Google session: she signs in (accounts.google.com/ServiceLogin) with the
// webmail as the page to return to, reads her inbox and opens the message Rallly sent her tagged address
const email = 'maya.okafor@gmail.com', tagged = 'maya.okafor+rallly@gmail.com';
const signin = await fetch('https://accounts.google.com/ServiceLogin', {
  method: 'POST', redirect: 'manual', headers: { 'content-type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({ email, password: readFileSync('.maya-password', 'utf8'), continue: 'https://mail.google.com/mail/u/0/' }),
});
assert.equal(signin.status, 302, 'Google signs Maya in and returns her to her inbox');
assert.equal(signin.headers.get('location'), 'https://mail.google.com/mail/u/0/');
const sid = /(?:^|[,;]\s*)SID=([^;]+)/.exec(signin.headers.get('set-cookie') ?? '')?.[1];
assert.ok(sid, 'the sign-in sets her Google session');
const cookie = `SID=${sid}`;
const inbox = await fetch('https://mail.google.com/mail/u/0/', { headers: { cookie } });
assert.equal(inbox.status, 200);
const listed = await inbox.text();
assert.match(listed, /Your poll has been finalized/, 'the inbox lists Rallly\'s message');
const id = /href="https:\/\/mail\.google\.com\/mail\/u\/0\/inbox\/([^"]+)"/.exec(listed)?.[1];
assert.ok(id, 'the message opens from the inbox');
const opened = await fetch(`https://mail.google.com/mail/u/0/inbox/${id}`, { headers: { cookie } });
assert.equal(opened.status, 200);
const page = await opened.text();
assert.ok(page.includes(tagged), 'the message is the one sent to her tagged address, kept in her own mailbox');
assert.match(page, /Thursday 22 January 2026 at 10:00/);
console.log(JSON.stringify({ readback: decodeURIComponent(id) }));
